window.kbPageData["views/entry/k-720e866ff4b2a5ef"] = {"key":"entry/k-720e866ff4b2a5ef","state":{"route":"entry/k-720e866ff4b2a5ef"},"node":{"id":"k-720e866ff4b2a5ef","mode":"k","title":"全球发展倡议、全球安全倡议、全球文明倡议、全球治理倡议","type":"观点与论证","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["open"],"主类":["观点与论证"],"出处性质":["机构注释"],"学科":["政治理论"],"来源主题":["发展与治理"],"资料类别":["非时政"]},"directorySummary":"2.全球发展倡议、全球安全倡议、全球文明倡议、全球治理倡议\n当今世界，和平赤字、发展赤字、安全赤字、治理赤字有增无减。提出构建人类命运共\n同体和全球发展倡议、全球安全倡议、全球文明倡议等，就是为了破解上述赤字，推动建设\n一个更加美好的世界，为各国人民创造更加美好的生活。\n（1）全球发展倡议：坚持发展…","sources":[{"id":"f58326ae99401036","label":"全球发展倡议、全球安全倡议、全球文明倡议、全球治理倡议","topic":"发展与治理","category":"非时政","text":"2.全球发展倡议、全球安全倡议、全球文明倡议、全球治理倡议\n当今世界，和平赤字、发展赤字、安全赤字、治理赤字有增无减。提出构建人类命运共\n同体和全球发展倡议、全球安全倡议、全球文明倡议等，就是为了破解上述赤字，推动建设\n一个更加美好的世界，为各国人民创造更加美好的生活。\n（1）全球发展倡议：坚持发展优先，坚持以人民为中心，坚持普惠包容，坚持创新驱\n动，坚持人与自然和谐共生，坚持行动导向。\n（2）全球安全倡议：坚持共同、综合、合作、可持续的安全观，坚持尊重各国主权、\n领土完整，坚持遵守联合国宪章宗旨和原则，坚持重视各国合理安全关切，坚持通过对话协\n商以和平方式解决国家间的分歧和争端，坚持统筹维护传统领域和非传统领域安全。\n（3）全球文明倡议：共同倡导尊重世界文明多样性，共同倡导弘扬全人类共同价值，\n共同倡导重视文明传承和创新，共同倡导加强国际人文交流合作。\n（4）全球治理倡议：第一，奉行主权平等。第二，遵守国际法治。第三，践行多边主\n义。第四，倡导以人为本。第五，注重行动导向。\n——《求是》杂志文章《推动落实全球发展倡议、全球安全倡议、全球文明倡议、全球\n治理倡议》","source":{"doc":"6cbfb01fe723bba64b75","first":56,"last":56,"page":56,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"open","title":"高水平开放与经贸规则"}],"units":{"k-720e866ff4b2a5ef":[]}};
